package com.oms.order.service;

import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import static com.oms.order.service.OrderValues.*;
import static org.junit.jupiter.api.Assertions.*;

class OrderUpdateServiceTest {
    static JdbcTemplate db;OrderRepository repo;OrderUpdateService updates;long platform,order;String original;
    @BeforeAll static void start(){String url=System.getenv("ORDER_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/order_workspace_test?"));db=new JdbcTemplate(new DriverManagerDataSource(url,"root",System.getenv("INVENTORY_TEST_PASSWORD")));}
    @BeforeEach void reset(){
        for(String t:Arrays.asList("oms_exchange_update_link","oms_order_update","oms_order_cutoff_item","oms_order_cutoff","oms_order_shipment_dispatch","oms_order_shipment_line","oms_order_shipment","oms_order_process_log","oms_order_line","oms_order","oms_platform_order_line","oms_platform_order","oms_order_pull_config"))db.update("DELETE FROM "+t);
        repo=new OrderRepository();ReflectionTestUtils.setField(repo,"jdbc",db);updates=new OrderUpdateService(repo);original=TmallOrderParserTest.payload("25");
        db.update("INSERT INTO oms_order_pull_config(company_code,channel_id,channel_name,source_key,seller_nick,initial_time,cursor_time) VALUES ('VERIFY',1,'fixture','fixture','seller',NOW(),NOW())");
        platform=repo.insert("INSERT INTO oms_platform_order(company_code,channel_id,platform_tid,platform_status,trade_type,seller_nick,source_modified,payload_hash,raw_payload,processing_payload,processing_hash,conversion_status,demand_registered) VALUES ('VERIFY',1,'987654321012345678','WAIT_SELLER_SEND_GOODS','fixed','seller','2026-10-01 00:00:00',?,?,?,?,'SUCCESS',1)",hash(original),original,original,hash(original));
        order=repo.insert("INSERT INTO oms_order(company_code,order_sn,channel_id,platform_order_id,platform_tid,inventory_status,payment,review_status) VALUES ('VERIFY','SO_UPDATE',1,?,'987654321012345678','RESERVED',25,'APPROVED')",platform);
        db.update("UPDATE oms_platform_order SET business_order_id=? WHERE id=?",order,platform);db.update("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,reserved_quantity) VALUES ('VERIFY',?,'987654321012345679','A','fixture',5,25,5)",order);
    }
    String changed(String key,String value){try{ObjectNode n=(ObjectNode)JSON.readTree(original);((ObjectNode)n.path("trade_fullinfo_get_response").path("trade")).put(key,value);return n.toString();}catch(Exception e){throw new RuntimeException(e);}}
    String lineChanged(String key,String value){try{ObjectNode n=(ObjectNode)JSON.readTree(original);((ObjectNode)n.path("trade_fullinfo_get_response").path("trade").path("orders").path("order").get(0)).put(key,value);return n.toString();}catch(Exception e){throw new RuntimeException(e);}}
    Map<String,Object> ingest(String payload,String time){Map<String,Object> row=new LinkedHashMap<>();row.put("jdp_response",payload);row.put("jdp_modified",time);row.put("modified",time);row.put("status",new TmallOrderParser().parse(payload).status);row.put("type","fixed");return new TransactionTemplate(new DataSourceTransactionManager(db.getDataSource())).execute(s->updates.ingest("VERIFY",repo.raw("VERIFY",platform),row));}
    Map<String,Object> p(){return repo.raw("VERIFY",platform);}
    Map<String,Object> command(){Map<String,Object> r=new HashMap<>();r.put("update_version",p().get("update_version"));r.put("reason","客户已确认");return r;}
    long n(String q){return db.queryForObject(q,Long.class);}
    @Test void goodsQuantityChangesBlockWithoutChangingDemandOrInventory(){ingest(lineChanged("num","8"),"2026-10-01 01:00:00");assertEquals(1,number(p(),"change_pending"));assertTrue(text(p(),"update_categories").contains("GOODS"));assertEquals(5,n("SELECT quantity FROM oms_order_line"));assertEquals(5,n("SELECT reserved_quantity FROM oms_order_line"));assertEquals(original,p().get("processing_payload"));}
    @Test void duplicateOldAndFormattingOnlyUpdatesDoNotCreateJournalNoise(){String changed=changed("receiver_state","上海市");ingest(changed,"2026-10-01 01:00:00");ingest(changed,"2026-10-01 02:00:00");ingest(original,"2026-10-01 00:30:00");assertEquals(1,n("SELECT COUNT(*) FROM oms_order_update"));assertEquals(changed,p().get("raw_payload"));assertEquals(1,number(p(),"update_version"));}
    @Test void sameTimestampConflictsAreRetainedAndCannotApplyOrReplaceLatest(){String a=changed("receiver_state","上海市"),b=changed("receiver_state","广东省");ingest(a,"2026-10-01 01:00:00");ingest(b,"2026-10-01 01:00:00");ingest(b,"2026-10-01 01:00:00");assertEquals(a,p().get("raw_payload"));assertEquals("ERROR",p().get("update_state"));assertEquals(2,n("SELECT COUNT(*) FROM oms_order_update"));assertThrows(IllegalArgumentException.class,()->updates.applyRecipient("VERIFY",platform,command(),"test"));}
    @Test void addressUpdateResetsReviewAndPolicyButPreservesHoldAndStock(){db.update("UPDATE oms_order SET manual_hold=1,hold_reason='人工核对',allocation_policy='{}'");ingest(changed("receiver_state","上海市"),"2026-10-01 01:00:00");updates.applyRecipient("VERIFY",platform,command(),"test");assertEquals(0,number(p(),"change_pending"));Map<String,Object> o=db.queryForMap("SELECT * FROM oms_order");assertEquals("PENDING",o.get("review_status"));assertEquals(1,number(o,"manual_hold"));assertNull(o.get("allocation_policy"));assertEquals(5,n("SELECT reserved_quantity FROM oms_order_line"));assertTrue(text(p(),"processing_payload").contains("上海市"));}
    @Test void applyingAddressDoesNotAdoptQuantityOrClearOtherBlockers() throws Exception {ObjectNode root=(ObjectNode)JSON.readTree(lineChanged("num","8"));((ObjectNode)root.path("trade_fullinfo_get_response").path("trade")).put("receiver_state","上海市");ingest(root.toString(),"2026-10-01 01:00:00");updates.applyRecipient("VERIFY",platform,command(),"test");assertEquals("GOODS",p().get("update_categories"));assertEquals(1,number(p(),"change_pending"));assertEquals(5,new TmallOrderParser().parse(text(p(),"processing_payload")).lines.get(0).quantity);assertEquals(5,n("SELECT quantity FROM oms_order_line"));}
    @Test void newVersionAndCrossCompanyCannotBeApplied(){ingest(changed("receiver_state","上海市"),"2026-10-01 01:00:00");Map<String,Object> old=command();ingest(changed("receiver_state","广东省"),"2026-10-01 02:00:00");assertThrows(IllegalArgumentException.class,()->updates.applyRecipient("VERIFY",platform,old,"test"));assertThrows(IllegalArgumentException.class,()->updates.report("OTHER",platform));assertThrows(IllegalArgumentException.class,()->updates.applyRecipient("OTHER",platform,command(),"test"));}
    @Test void unwithdrawnShipmentAndUncertainAllocationPreventAddressAdoption(){long shipment=repo.insert("INSERT INTO oms_order_shipment(company_code,shipment_sn,order_id,order_sn,channel_id,platform_tid,generation_no,owner_code,real_store_code,real_store_name,quantity,created_by) VALUES ('VERIFY','XS_UPDATE',?,'SO_UPDATE',1,'987654321012345678',1,'O','R','R',5,'test')",order);db.update("INSERT INTO oms_order_shipment_line(company_code,shipment_id,order_line_id,platform_oid,sku_sn,goods_name,quantity,allocation_id,stock_source_id,store_code,batch_id,source_type) VALUES ('VERIFY',?,1,'987654321012345679','A','fixture',5,1,1,'V',1,'PUBLIC_EXTRA')",shipment);ingest(changed("receiver_state","上海市"),"2026-10-01 01:00:00");assertThrows(IllegalArgumentException.class,()->updates.applyRecipient("VERIFY",platform,command(),"test"));db.update("UPDATE oms_order_shipment SET status='VOIDED'");db.update("UPDATE oms_order SET allocation_status='UNCERTAIN'");assertThrows(IllegalArgumentException.class,()->updates.applyRecipient("VERIFY",platform,command(),"test"));assertEquals(original,p().get("processing_payload"));}
    @Test void refundSuccessRemainsPendingWhenLaterPayloadOmitsRefund(){ingest(lineChanged("refund_status","SUCCESS"),"2026-10-01 01:00:00");ingest(original,"2026-10-01 02:00:00");assertEquals(1,number(p(),"change_pending"));assertTrue(text(p(),"update_categories").contains("REFUND"));assertEquals(5,n("SELECT reserved_quantity FROM oms_order_line"));}
    @Test void refundWithdrawalDoesNotClearIndependentGoodsChange() throws Exception {ObjectNode root=(ObjectNode)JSON.readTree(lineChanged("num","8"));((ObjectNode)root.path("trade_fullinfo_get_response").path("trade")).put("refund_status","WAIT_SELLER_AGREE");ingest(root.toString(),"2026-10-01 01:00:00");ingest(lineChanged("num","8"),"2026-10-01 02:00:00");assertEquals("GOODS",p().get("update_categories"));assertEquals(1,number(p(),"change_pending"));}
    @Test void displayOnlyAndEquivalentNumericValuesDoNotBlock(){ingest(lineChanged("title","新展示标题"),"2026-10-01 01:00:00");assertEquals(0,number(p(),"change_pending"));assertEquals("COMPLETED",p().get("update_state"));ingest(changed("payment","25.00"),"2026-10-01 02:00:00");assertEquals(0,number(p(),"change_pending"));}
    @Test void forwardPlatformStatusWithoutActualShipmentRequiresReconciliation(){ingest(changed("status","WAIT_BUYER_CONFIRM_GOODS"),"2026-10-01 01:00:00");assertTrue(text(p(),"update_categories").contains("STATUS"));assertEquals(1,number(p(),"change_pending"));assertEquals(5,n("SELECT reserved_quantity FROM oms_order_line"));}
    @Test void reportNeverReturnsRawSnapshotsOrOtherCompanyHistory(){ingest(changed("payment","30"),"2026-10-01 01:00:00");Map<String,Object> report=updates.report("VERIFY",platform);assertFalse(report.containsKey("payload"));assertFalse(report.containsKey("raw_payload"));assertTrue(report.get("history") instanceof List);assertTrue(report.get("differences") instanceof List);assertThrows(IllegalArgumentException.class,()->updates.report("OTHER",platform));}
    @Test void newerConfirmedSourceCanResolveConflictWithoutChangingContent(){String a=changed("receiver_state","上海市");ingest(a,"2026-10-01 01:00:00");ingest(changed("receiver_state","广东省"),"2026-10-01 01:00:00");ingest(a,"2026-10-01 02:00:00");assertEquals("WAITING",p().get("update_state"));assertEquals("RECIPIENT",p().get("update_categories"));updates.applyRecipient("VERIFY",platform,command(),"test");assertEquals(0,number(p(),"change_pending"));}
    @Test void registeredDemandWithoutSnapshotKeepsOriginalBaselineAcrossSuccessiveUpdates(){db.update("UPDATE oms_platform_order SET processing_payload=NULL,processing_hash=NULL");ingest(lineChanged("num","8"),"2026-10-01 01:00:00");ingest(changed("receiver_state","上海市"),"2026-10-01 02:00:00");assertEquals(original,p().get("processing_payload"));assertEquals("RECIPIENT",p().get("update_categories"));}
    @Test void withdrawnRefundRequiresFreshReviewBeforeQueuedDispatchCouldResume(){ingest(lineChanged("refund_status","WAIT_SELLER_AGREE"),"2026-10-01 01:00:00");ingest(original,"2026-10-01 02:00:00");assertEquals(0,number(p(),"change_pending"));assertEquals("PENDING",db.queryForObject("SELECT review_status FROM oms_order",String.class));assertEquals("MANUAL_REQUIRED",db.queryForObject("SELECT review_decision FROM oms_order",String.class));}
    @Test void pendingFilterUsesCurrentProjectionAndKeepsCompanyScope(){ingest(changed("receiver_state","上海市"),"2026-10-01 01:00:00");OrderBusinessService b=new OrderBusinessService();ReflectionTestUtils.setField(b,"repository",repo);assertEquals(1,b.list("VERIFY",null,"","","","","",0,1,20,"","","","","","","","WAITING").getTotal());assertEquals(0,b.list("OTHER",null,"","","","","",0,1,20,"","","","","","","","WAITING").getTotal());assertEquals(0,b.list("VERIFY",null,"","","","","",0,1,20,"","","","","","","","ERROR").getTotal());}
    long shipped(){long s=repo.insert("INSERT INTO oms_order_shipment(company_code,shipment_sn,order_id,order_sn,channel_id,platform_tid,generation_no,owner_code,real_store_code,real_store_name,quantity,status,receiver_address,created_by) VALUES ('VERIFY','XS_DONE',?,'SO_UPDATE',1,'987654321012345678',1,'O','R','R',5,'SHIPPED','原发货地址','test')",order);db.update("INSERT INTO oms_order_shipment_line(company_code,shipment_id,order_line_id,platform_oid,sku_sn,goods_name,quantity,shipped_quantity,allocation_id,stock_source_id,store_code,batch_id,source_type) VALUES ('VERIFY',?,1,'987654321012345679','A','fixture',5,5,1,1,'V',1,'PUBLIC_EXTRA')",s);return s;}
    @Test void normalForwardStatusAfterActualShippingIsSynchronizedWithoutFalseChange(){shipped();ingest(changed("status","WAIT_BUYER_CONFIRM_GOODS"),"2026-10-01 01:00:00");assertEquals(0,number(p(),"change_pending"));assertEquals("COMPLETED",p().get("update_state"));assertEquals("APPROVED",db.queryForObject("SELECT review_status FROM oms_order",String.class));}
    @Test void allShippedAddressChangeCannotOverwriteShipmentSnapshot(){shipped();ingest(changed("receiver_state","上海市"),"2026-10-01 01:00:00");assertThrows(IllegalArgumentException.class,()->updates.applyRecipient("VERIFY",platform,command(),"test"));assertEquals("APPROVED",db.queryForObject("SELECT review_status FROM oms_order",String.class));assertEquals("原发货地址",db.queryForObject("SELECT receiver_address FROM oms_order_shipment",String.class));assertEquals(original,p().get("processing_payload"));}
    @Test void ambiguousSpecificationChangesAreConservativelyBlocked(){ingest(lineChanged("sku_properties_name","颜色:蓝;尺码:L"),"2026-10-01 01:00:00");assertTrue(text(p(),"update_categories").contains("GOODS"));assertEquals(5,n("SELECT reserved_quantity FROM oms_order_line"));}
    @Test void historicalDifferencesAreLazyAndBoundToCompanyAndParent(){ingest(changed("payment","30"),"2026-10-01 01:00:00");Map<String,Object> r=updates.report("VERIFY",platform);Map<String,Object> event=(Map<String,Object>)((List<?>)r.get("history")).get(0);assertFalse(event.containsKey("differences"));assertTrue(updates.event("VERIFY",platform,number(event,"id")).get("differences") instanceof List);assertThrows(IllegalArgumentException.class,()->updates.event("OTHER",platform,number(event,"id")));assertThrows(IllegalArgumentException.class,()->updates.event("VERIFY",platform,number(event,"id")+1));}
    @Test void withdrawalRetryUsesOriginalOperationInsteadOfCreatingAnother(){ingest(changed("receiver_state","上海市"),"2026-10-01 01:00:00");long op=repo.insert("INSERT INTO oms_order_cutoff(company_code,order_id,mode,scope_all,reason,operator_name) VALUES ('VERIFY',?,'REPLAN',1,'fixture','test')",order);db.update("UPDATE oms_order_update SET cutoff_id=? WHERE company_code='VERIFY' AND platform_order_id=?",op,platform);OrderCutoffService cutoff=org.mockito.Mockito.mock(OrderCutoffService.class);updates.prepare("VERIFY",platform,command(),"test",cutoff);org.mockito.Mockito.verifyNoInteractions(cutoff);assertEquals(1,n("SELECT COUNT(*) FROM oms_order_cutoff"));}
    @Test void exchangeCoverageOnlyClearsItsExactGoodsDifferenceAndPreservesRefund() throws Exception {
        ObjectNode next=(ObjectNode)JSON.readTree(original);ObjectNode target=(ObjectNode)next.path("trade_fullinfo_get_response").path("trade").path("orders").path("order").get(0);target.put("outer_sku_id","B");target.put("refund_status","WAIT_SELLER_AGREE");ingest(next.toString(),"2026-10-01 01:00:00");
        Map<String,Object> d=updates.differences(original,next.toString()).stream().filter(v->"outer_sku_id".equals(text(v,"field"))).findFirst().get();
        db.update("INSERT INTO oms_exchange_update_link(company_code,exchange_id,platform_order_id,update_id,source_hash,field_path,difference_hash,difference,state) VALUES ('VERIFY',1,?,1,?,?,?,?, 'APPLIED')",platform,hash(next.toString()),"987654321012345679/outer_sku_id",hash(ExchangeService.canonical(d)),encode(d));updates.refreshProjection("VERIFY",platform);assertEquals("REFUND",p().get("update_categories"));assertEquals(1,number(p(),"change_pending"));
        target.put("outer_sku_id","C");ingest(next.toString(),"2026-10-01 02:00:00");assertTrue(text(p(),"update_categories").contains("GOODS"));assertTrue(text(p(),"update_categories").contains("REFUND"));
    }

    @Test void freightDiscountAndPriceChangesPauseWithoutOverwritingAdoptedMoney(){
        Map<String,Object> doc=OrderDocumentInfo.fromPayload(original);db.update("UPDATE oms_order SET document_info=?",encode(doc));
        ingest(changed("post_fee","10.00"),"2026-10-01 01:00:00");assertEquals(1,number(p(),"change_pending"));assertTrue(text(p(),"update_categories").contains("AMOUNT"));
        assertNull(OrderDocumentInfo.stored(db.queryForObject("SELECT document_info FROM oms_order",String.class)).get("buyer_freight"));
        assertEquals("10.00",OrderDocumentInfo.stored(p().get("document_info")).get("buyer_freight"));assertEquals(5,n("SELECT reserved_quantity FROM oms_order_line"));
        ingest(lineChanged("price","12.00"),"2026-10-01 02:00:00");assertTrue(text(p(),"update_categories").contains("AMOUNT"));
        ingest(changed("discount_fee","2.00"),"2026-10-01 03:00:00");assertTrue(text(p(),"update_categories").contains("AMOUNT"));
    }
    @Test void displayMetadataRefreshesWithoutPausingOrChangingOriginalAmounts(){
        Map<String,Object> doc=OrderDocumentInfo.fromPayload(original);db.update("UPDATE oms_order SET document_info=?",encode(doc));
        ingest(changed("buyer_message","请分开包装"),"2026-10-01 01:00:00");assertEquals(0,number(p(),"change_pending"));
        Map<String,Object> adopted=OrderDocumentInfo.stored(db.queryForObject("SELECT document_info FROM oms_order",String.class));assertEquals("请分开包装",adopted.get("buyer_message"));assertEquals("25.00",adopted.get("payment"));assertEquals("APPROVED",db.queryForObject("SELECT review_status FROM oms_order",String.class));
    }
}
